function Shot([string]$path,[int]$w,[int]$h){$dir=Split-Path -Parent $path;if(-not(Test-Path $dir)){[IO.Directory]::CreateDirectory($dir)|Out-Null};$window.UpdateLayout();[double]$dpiX=96.0*$w/[Math]::Max(1.0,[double]$window.ActualWidth);[double]$dpiY=96.0*$h/[Math]::Max(1.0,[double]$window.ActualHeight);$render=New-Object Windows.Media.Imaging.RenderTargetBitmap -ArgumentList $w,$h,$dpiX,$dpiY,([Windows.Media.PixelFormats]::Pbgra32);$render.Render($window);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($render));$stream=[IO.File]::Open([IO.Path]::GetFullPath($path),[IO.FileMode]::Create);try{$encoder.Save($stream)}finally{$stream.Dispose()}}
